// Replaces every attractions record's loremflickr.com image with a local
// SVG illustration (generated by scripts/generate-card-art.js), and fixes
// the loremflickr URL baked into the attractions section-hero banner in
// index.html. Idempotent: records already migrated (no loremflickr src) are
// left untouched, so re-running after a successful pass is a no-op.
//
// Usage: node scripts/replace-placeholder-images.js
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const LOCATIONS_PATH = path.join(ROOT, 'js', 'locations-data.js');
const INDEX_PATH = path.join(ROOT, 'index.html');

const { THEMES } = require('./generate-card-art.js');

// Primary tag (first entry of the comma-separated `tags` field) -> theme
// file in images/cards/. One-to-one with the six loremflickr keyword
// categories used across the 40 seeded attraction records.
const THEME_MAP = {
    history: 'history',
    nature: 'nature',
    beach: 'beach',
    village: 'village',
    family: 'family',
    food: 'food'
};

for (const theme of Object.values(THEME_MAP)) {
    if (!THEMES.includes(theme)) {
        throw new Error(`THEME_MAP references theme "${theme}" with no matching images/cards/${theme}.svg`);
    }
}

global.window = {};
require(LOCATIONS_PATH);
const L = global.window.CORFU_LOCATIONS;

let replaced = 0;
let alreadyLocal = 0;

(L.attractions || []).forEach((record) => {
    const src = record.image && record.image.src;
    if (!src || !src.includes('loremflickr.com')) {
        alreadyLocal++;
        return;
    }

    const primaryTag = (record.tags || '').split(',')[0].trim();
    const theme = THEME_MAP[primaryTag];
    if (!theme) {
        throw new Error(`No illustration theme for record "${record.id}" (primary tag "${primaryTag}")`);
    }

    record.image = {
        src: `images/cards/${theme}.svg`,
        alt: `איור בסגנון המדריך: ${record.title || record.name || theme}`,
        isIllustration: true
    };
    replaced++;
});

const header = fs.readFileSync(LOCATIONS_PATH, 'utf8').match(/^[\s\S]*?window\.CORFU_LOCATIONS = /)[0];
fs.writeFileSync(LOCATIONS_PATH, header + JSON.stringify(L, null, 2) + ';\n', 'utf8');

// Fix the loremflickr reference in index.html's attractions section-hero banner.
let indexHtml = fs.readFileSync(INDEX_PATH, 'utf8');
const bannerBefore = indexHtml;
indexHtml = indexHtml.replace(
    /<img src="https:\/\/loremflickr\.com\/[^"]*"([^>]*class="section-hero-banner-img"[^>]*)>/,
    '<img src="images/cards/banner-attractions.svg"$1>'
);
const bannerFixed = indexHtml !== bannerBefore;
fs.writeFileSync(INDEX_PATH, indexHtml, 'utf8');

const remainingLoremflickr =
    (fs.readFileSync(LOCATIONS_PATH, 'utf8').match(/loremflickr/g) || []).length +
    (fs.readFileSync(INDEX_PATH, 'utf8').match(/loremflickr/g) || []).length;

console.log('=== replace-placeholder-images.js summary ===');
console.log(`Records replaced this run: ${replaced}`);
console.log(`Records already local:     ${alreadyLocal}`);
console.log(`Banner href fixed:         ${bannerFixed}`);
console.log(`Remaining loremflickr occurrences (code, not comments): ${remainingLoremflickr}`);
